#include "../RahiTuber/MaxFaceLayer.h"
#include <stdexcept>
#include <iostream>
int main(){std::vector<unsigned char> image(256*192*4,255);for(int y=0;y<192;++y)for(int x=0;x<256;++x){auto i=(y*256+x)*4;image[i]=x;image[i+1]=image[i+2]=64;}MaxFaceLayer c;c.zoom=1;c.mask=2;c.brightness=1;auto p=MaxFacePixels(image.data(),256,192,c);auto centre=(96*256+128)*4;if(std::abs(int(p[centre+1])-128)>1)throw std::runtime_error("Brightness calculation failed");c.brightness=0;c.panX=.1f;p=MaxFacePixels(image.data(),256,192,c);if(p[centre]<150)throw std::runtime_error("Crop pan failed");c.panX=0;c.zoom=2;p=MaxFacePixels(image.data(),256,192,c);if(p[(96*256+64)*4]<90)throw std::runtime_error("Source zoom failed");c.mask=0;p=MaxFacePixels(image.data(),256,192,c);if(p[3]!=0||p[centre+3]!=255)throw std::runtime_error("Soft mask alpha failed");for(std::size_t i=0;i<p.size();i+=4)if(p[i]>p[i+3]||p[i+1]>p[i+3]||p[i+2]>p[i+3])throw std::runtime_error("Cutout alpha is not premultiplied");MaxFaceLayer other;other.height=.23f;other.rotation=14;c.zoom=3.2f;c.brightness=.7f;c.mask=1;MaxCopyFaceSettings(other,c);if(other.zoom!=c.zoom||other.brightness!=c.brightness||other.mask!=c.mask||other.height!=.23f||other.rotation!=14)throw std::runtime_error("Copy settings changed placement or missed crop settings");std::cout<<"PASS: crop pan, source zoom, brightness, soft masks and premultiplied alpha\n";}
